SELECT s.id, s.country, s.browser, t.page_view_duration_sec, t.min_duration_sec FROM sessions s INNER JOIN (SELECT session_id, SUM(CASE WHEN event_type = 'page_view' THEN duration_sec ELSE 0 END) AS page_view_duration_sec, MIN(duration_sec) AS min_duration_sec FROM web_events WHERE page IS NULL GROUP BY session_id) t ON s.id = t.session_id WHERE t.min_duration_sec > 220 ORDER BY browser;
